"""Command line implementation of the fulfillment workflow."""

from __future__ import annotations

import argparse
import csv
import itertools
import sys
from collections import defaultdict
from dataclasses import dataclass
from datetime import date
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Iterable, Sequence


class InputError(ValueError):
    """An input file is malformed or internally inconsistent."""


@dataclass(frozen=True)
class Order:
    order_id: str
    priority: str
    due_date: date
    allow_partial: bool


@dataclass(frozen=True)
class Line:
    order_id: str
    line_id: str
    sku: str
    requested_qty: int


@dataclass(frozen=True)
class ExistingAllocation:
    order_id: str
    line_id: str
    warehouse_id: str
    quantity: int
    status: str


@dataclass
class Candidate:
    new_allocations: dict[tuple[str, str], int]
    used: tuple[str, ...]
    complete_lines: int
    filled_units: int
    cost: Decimal

    @property
    def full(self) -> bool:
        return self.complete_lines == self._line_count

    # Set immediately after construction. Keeping it out of comparisons makes
    # Candidate a convenient internal record rather than part of the input API.
    _line_count: int = 0


PRIORITY_RANK = {"urgent": 0, "high": 1, "normal": 2}


def _read_csv(path: Path, expected_header: Sequence[str]) -> list[dict[str, str]]:
    try:
        handle = path.open("r", encoding="utf-8", newline="")
    except OSError as exc:
        raise InputError(f"cannot read {path}: {exc}") from exc
    with handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != list(expected_header):
            raise InputError(
                f"{path}: expected header {','.join(expected_header)!r}, "
                f"got {','.join(reader.fieldnames or [])!r}"
            )
        rows = []
        try:
            for row_number, row in enumerate(reader, start=2):
                if None in row or any(value is None for value in row.values()):
                    raise InputError(f"{path}:{row_number}: wrong number of fields")
                if any("\x00" in value for value in row.values()):
                    raise InputError(f"{path}:{row_number}: NUL byte in field")
                row["__row__"] = str(row_number)
                rows.append(row)
        except csv.Error as exc:
            raise InputError(f"{path}: invalid CSV: {exc}") from exc
        return rows


def _required(value: str, path: Path, row: int, field: str) -> str:
    if value == "":
        raise InputError(f"{path}:{row}: {field} must not be empty")
    return value


def _integer(value: str, path: Path, row: int, field: str, *, positive: bool) -> int:
    try:
        parsed = int(value)
    except ValueError as exc:
        raise InputError(f"{path}:{row}: {field} must be an integer") from exc
    if str(parsed) != value and not (value.startswith("+") and str(parsed) == value[1:]):
        raise InputError(f"{path}:{row}: {field} must be a plain base-10 integer")
    if (positive and parsed <= 0) or (not positive and parsed < 0):
        condition = "positive" if positive else "non-negative"
        raise InputError(f"{path}:{row}: {field} must be {condition}")
    return parsed


def _decimal(value: str, path: Path, row: int, field: str) -> Decimal:
    try:
        parsed = Decimal(value)
    except InvalidOperation as exc:
        raise InputError(f"{path}:{row}: {field} must be a decimal amount") from exc
    if not parsed.is_finite() or parsed < 0:
        raise InputError(f"{path}:{row}: {field} must be a finite non-negative decimal")
    return parsed


def _load_inputs(input_dir: Path):
    order_path = input_dir / "orders.csv"
    line_path = input_dir / "order_lines.csv"
    inventory_path = input_dir / "inventory.csv"
    costs_path = input_dir / "shipping_cost.csv"
    existing_path = input_dir / "existing_allocations.csv"

    orders: dict[str, Order] = {}
    for row in _read_csv(order_path, ("order_id", "priority", "due_date", "allow_partial")):
        number = int(row["__row__"])
        order_id = _required(row["order_id"], order_path, number, "order_id")
        if order_id in orders:
            raise InputError(f"{order_path}:{number}: duplicate order_id {order_id!r}")
        priority = row["priority"]
        if priority not in PRIORITY_RANK:
            raise InputError(f"{order_path}:{number}: invalid priority {priority!r}")
        try:
            due = date.fromisoformat(row["due_date"])
        except ValueError as exc:
            raise InputError(f"{order_path}:{number}: invalid due_date {row['due_date']!r}") from exc
        if row["allow_partial"] not in ("true", "false"):
            raise InputError(f"{order_path}:{number}: allow_partial must be true or false")
        orders[order_id] = Order(order_id, priority, due, row["allow_partial"] == "true")

    lines: dict[tuple[str, str], Line] = {}
    skus_by_order: set[tuple[str, str]] = set()
    for row in _read_csv(line_path, ("order_id", "line_id", "sku", "requested_qty")):
        number = int(row["__row__"])
        order_id = _required(row["order_id"], line_path, number, "order_id")
        line_id = _required(row["line_id"], line_path, number, "line_id")
        sku = _required(row["sku"], line_path, number, "sku")
        if order_id not in orders:
            raise InputError(f"{line_path}:{number}: unknown order_id {order_id!r}")
        key = (order_id, line_id)
        if key in lines:
            raise InputError(f"{line_path}:{number}: duplicate order/line {key!r}")
        if (order_id, sku) in skus_by_order:
            raise InputError(f"{line_path}:{number}: SKU {sku!r} occurs twice in order {order_id!r}")
        qty = _integer(row["requested_qty"], line_path, number, "requested_qty", positive=True)
        lines[key] = Line(order_id, line_id, sku, qty)
        skus_by_order.add((order_id, sku))

    shipping: dict[str, tuple[Decimal, Decimal]] = {}
    for row in _read_csv(costs_path, ("warehouse_id", "base_cost", "per_unit_cost")):
        number = int(row["__row__"])
        warehouse = _required(row["warehouse_id"], costs_path, number, "warehouse_id")
        if warehouse in shipping:
            raise InputError(f"{costs_path}:{number}: duplicate warehouse_id {warehouse!r}")
        shipping[warehouse] = (
            _decimal(row["base_cost"], costs_path, number, "base_cost"),
            _decimal(row["per_unit_cost"], costs_path, number, "per_unit_cost"),
        )
    if len(shipping) != 4:
        raise InputError(f"{costs_path}: expected exactly four warehouses, found {len(shipping)}")

    inventory: dict[tuple[str, str], int] = {}
    inventory_rows: list[tuple[str, str, int]] = []
    for row in _read_csv(inventory_path, ("warehouse_id", "sku", "on_hand")):
        number = int(row["__row__"])
        warehouse = _required(row["warehouse_id"], inventory_path, number, "warehouse_id")
        sku = _required(row["sku"], inventory_path, number, "sku")
        if warehouse not in shipping:
            raise InputError(f"{inventory_path}:{number}: unknown warehouse_id {warehouse!r}")
        key = (warehouse, sku)
        if key in inventory:
            raise InputError(f"{inventory_path}:{number}: duplicate warehouse/SKU {key!r}")
        qty = _integer(row["on_hand"], inventory_path, number, "on_hand", positive=False)
        inventory[key] = qty
        inventory_rows.append((warehouse, sku, qty))

    existing: list[ExistingAllocation] = []
    for row in _read_csv(
        existing_path, ("order_id", "line_id", "warehouse_id", "quantity", "status")
    ):
        number = int(row["__row__"])
        key = (row["order_id"], row["line_id"])
        if key not in lines:
            raise InputError(f"{existing_path}:{number}: unknown order/line {key!r}")
        warehouse = row["warehouse_id"]
        if warehouse not in shipping:
            raise InputError(f"{existing_path}:{number}: unknown warehouse_id {warehouse!r}")
        if row["status"] not in ("shipped", "reserved"):
            raise InputError(f"{existing_path}:{number}: invalid status {row['status']!r}")
        quantity = _integer(row["quantity"], existing_path, number, "quantity", positive=True)
        existing.append(ExistingAllocation(key[0], key[1], warehouse, quantity, row["status"]))

    return orders, lines, shipping, inventory, inventory_rows, existing


def _candidate(
    warehouse_tuple: tuple[str, ...],
    order_lines: Sequence[Line],
    available: dict[tuple[str, str], int],
    existing_by_line: dict[tuple[str, str], int],
    existing_by_warehouse: dict[str, int],
    existing_used: set[str],
    shipping: dict[str, tuple[Decimal, Decimal]],
) -> Candidate:
    new: dict[tuple[str, str], int] = {}
    filled_units = 0
    complete = 0
    for line in order_lines:
        prior = existing_by_line.get((line.order_id, line.line_id), 0)
        need = line.requested_qty - prior
        remaining_need = need
        for warehouse in sorted(warehouse_tuple, key=lambda wh: (shipping[wh][1], wh)):
            quantity = min(remaining_need, available.get((warehouse, line.sku), 0))
            if quantity:
                new[(line.line_id, warehouse)] = quantity
                remaining_need -= quantity
            if remaining_need == 0:
                break
        line_filled = prior + need - remaining_need
        filled_units += line_filled
        if line_filled == line.requested_qty:
            complete += 1

    used_set = existing_used | {warehouse for (_, warehouse), qty in new.items() if qty > 0}
    used = tuple(sorted(used_set))
    units_by_warehouse = dict(existing_by_warehouse)
    for (_, warehouse), quantity in new.items():
        units_by_warehouse[warehouse] = units_by_warehouse.get(warehouse, 0) + quantity
    cost = sum(
        (shipping[warehouse][0] + shipping[warehouse][1] * units_by_warehouse[warehouse]
         for warehouse in used),
        Decimal(0),
    )
    return Candidate(new, used, complete, filled_units, cost, len(order_lines))


